import React from 'react';
import { Card, Row, Col, Button, List, Avatar, Badge } from 'antd';
import { Line, Pie } from '@ant-design/charts';
import {
    CarOutlined,
    WarningOutlined,
    VideoCameraOutlined,
    RiseOutlined,
    ClockCircleOutlined,
} from '@ant-design/icons';
import './Dashboard.css'; // 自定义样式

const Dashboard = () => {
    // 模拟数据
    const coreData = [
        { title: '今日检测总车辆数', value: '3,250', icon: <CarOutlined />, color: '#1890ff' },
        { title: '今日异常车辆数', value: '15', icon: <WarningOutlined />, color: '#ff4d4f' },
        { title: '当前在线摄像头数', value: '12 / 15', icon: <VideoCameraOutlined />, color: '#52c41a' },
        { title: '车辆流量趋势', value: '+5%', icon: <RiseOutlined />, color: '#faad14' },
        { title: '系统响应速度', value: '120ms', icon: <ClockCircleOutlined />, color: '#722ed1' },
        { title: '平均检测耗时', value: '20ms', icon: <CarOutlined />, color: '#4b4453' },
    ];

    // 车流量折线图数据
    const lineData = [
        { time: '00:00', value: 120, type: '小汽车' },
        { time: '01:00', value: 80, type: '小汽车' },
        { time: '02:00', value: 60, type: '小汽车' },
        { time: '03:00', value: 90, type: '小汽车' },
        { time: '04:00', value: 150, type: '小汽车' },
        { time: '00:00', value: 30, type: '货车' },
        { time: '01:00', value: 20, type: '货车' },
        { time: '02:00', value: 15, type: '货车' },
        { time: '03:00', value: 25, type: '货车' },
        { time: '04:00', value: 40, type: '货车' },
    ];

    // 车辆类型占比饼图数据
    const pieData = [
        { type: '小汽车', value: 75 },
        { type: '货车', value: 15 },
        { type: '公交车', value: 5 },
        { type: '特殊车辆', value: 5 },
    ];

    // 违规车辆列表数据
    const violateData = [
        { id: 1, plate: '粤A12345', type: '小汽车', time: '2023-10-01 12:30', reason: '危险车辆进入', status: '未处理' },
        { id: 2, plate: '粤B67890', type: '货车', time: '2023-10-01 13:00', reason: '超速行驶', status: '已查看' },
        { id: 3, plate: '粤C11223', type: '公交车', time: '2023-10-01 13:30', reason: '违规停车', status: '已处理' },
    ];

    // 折线图配置
    const lineConfig = {
        data: lineData,
        xField: 'time',
        yField: 'value',
        seriesField: 'type',
        xAxis: { title: { text: '时间' } },
        yAxis: { title: { text: '车辆数' } },
        legend: { position: 'top' },
        smooth: true,
    };

    // 饼图配置
    const pieConfig = {
        data: pieData,
        angleField: 'value',
        colorField: 'type',
        radius: 0.8,
        label: {  offset: '-30%', content: '{percentage}' },
        interactions: [{ type: 'element-active' }],
    };

    return (
        <div className="dashboard">
            {/* 核心数据卡片 */}
            <Row gutter={[16, 16]} className="core-data">
                {coreData.map((item, index) => (
                    <Col key={index} span={4}>
                        <Card style={{ backgroundColor: item.color, color: '#fff' }}>
                            <div className="card-content">
                                {item.icon}
                                <h3>{item.title}</h3>
                                <p>{item.value}</p>
                            </div>
                        </Card>
                    </Col>
                ))}
            </Row>

            {/* 车流量统计图表 */}
            <Row gutter={[8, 8]} className="charts">
                <Col span={14}>
                    <Card title="车流量趋势分析" style={{ height: 480 }}>
                        <Line {...lineConfig} height={330} />
                    </Card>
                </Col>
                <Col span={10}>
                    <Card title="车辆类型占比" style={{ height: 480 }}>
                        <Pie {...pieConfig} height={330} />
                    </Card>
                </Col>
            </Row>


            {/* 实时监控窗口 */}
            <Card title="实时监控" className="monitor">
                <Row gutter={[16, 16]}>
                    {[1, 2, 3, 4].map((item) => (
                        <Col key={item} span={6}>
                            <div className="camera-preview">
                                <VideoCameraOutlined />
                                <p>摄像头 {item}</p>
                            </div>
                        </Col>
                    ))}
                </Row>
            </Card>

            {/* 违规车辆提醒 */}
            <Card title="违规车辆提醒" className="violate-list">
                <List
                    dataSource={violateData}
                    renderItem={(item) => (
                        <List.Item>
                            <List.Item.Meta
                                avatar={<Avatar src={`https://i.pravatar.cc/150?u=${item.id}`} />}
                                title={item.plate}
                                description={`${item.type} | ${item.time} | ${item.reason}`}
                            />
                            <Badge
                                status={
                                    item.status === '未处理'
                                        ? 'error'
                                        : item.status === '已查看'
                                            ? 'warning'
                                            : 'success'
                                }
                                text={item.status}
                            />
                        </List.Item>
                    )}
                />
            </Card>

            {/* 快捷操作按钮 */}
            <div className="quick-actions">
                <Button type="primary" icon={<CarOutlined />}>
                    手动上传图片检测
                </Button>
                <Button type="primary" icon={<VideoCameraOutlined />}>
                    上传视频检测
                </Button>
                <Button type="primary" icon={<ClockCircleOutlined />}>
                    查询历史记录
                </Button>
                <Button type="primary" icon={<RiseOutlined />}>
                    系统设置
                </Button>
            </div>
        </div>
    );
};

export default Dashboard;