import React, { useState } from 'react';
import { Layout, Table, Button, Input, Select, Modal, Tag } from 'antd';
import { SearchOutlined, FileExcelOutlined, FilePdfOutlined } from '@ant-design/icons';
import { useNavigate } from 'react-router-dom';
import './Violate.css';
import Car1 from "../assets/车1.png"
import Car2 from "../assets/车2.png"
import Car3 from "../assets/车3.png"
const { Header, Content, Sider } = Layout;
const { Option } = Select;

// 模拟数据
const violationData = [
    { id: 1, plate: '粤A12345', type: '超速', time: '2025-03-10 12:30', status: '未处理', location: '长安校区', image: Car1 },
    { id: 2, plate: '粤B67890', type: '非法停车', time: '2025-03-11 14:00', status: '处理中', location: '友谊校区', image: Car2 },
    { id: 3, plate: '粤C11223', type: '禁行区域驶入', time: '2025-03-12 16:20', status: '已处理', location: '国际校区', image: Car3 },
];

const Violate = () => {
    const [searchText, setSearchText] = useState('');
    const [filteredData, setFilteredData] = useState(violationData);
    const navigate = useNavigate();

    // 处理搜索
    const handleSearch = () => {
        const filtered = violationData.filter(item =>
            item.plate.includes(searchText) || item.type.includes(searchText)
        );
        setFilteredData(filtered);
    };

    // 处理状态颜色
    const statusColor = {
        "未处理": "red",
        "处理中": "orange",
        "已处理": "green"
    };

    // 处理详情跳转
    const handleViewDetail = (id) => {
        navigate(`/violate/${id}`);
    };

    // 违规车辆表格列配置
    const columns = [
        {
            title: '缩略图',
            dataIndex: 'image',
            render: (img) => <img src={img} alt="车辆" style={{ width: 60 }} />,
        },
        {
            title: '车牌号',
            dataIndex: 'plate',
            sorter: (a, b) => a.plate.localeCompare(b.plate),
        },
        {
            title: '违规类型',
            dataIndex: 'type',
        },
        {
            title: '检测时间',
            dataIndex: 'time',
            sorter: (a, b) => new Date(a.time) - new Date(b.time),
        },
        {
            title: '处理状态',
            dataIndex: 'status',
            render: (status) => <Tag color={statusColor[status]}>{status}</Tag>,
        },
        {
            title: '操作',
            render: (_, record) => (
                <Button type="link" onClick={() => handleViewDetail(record.id)}>查看详情</Button>
            ),
        },
    ];

    return (
        <Layout>
            <Sider width={200} className="sider">
                <div className="menu">
                    <p>🚗 违规车辆管理</p>
                    <p>📊 统计分析</p>
                    <p>📝 处理记录</p>
                    <p>⚙️ 系统设置</p>
                </div>
            </Sider>
            <Layout>
                <Header className="header">
                    <Input
                        placeholder="输入车牌号/违规类型"
                        value={searchText}
                        onChange={(e) => setSearchText(e.target.value)}
                        style={{ width: 200, marginRight: 10 }}
                    />
                    <Button icon={<SearchOutlined />} onClick={handleSearch}>搜索</Button>
                    <Button icon={<FileExcelOutlined />} style={{ marginLeft: 10 }}>导出Excel</Button>
                    <Button icon={<FilePdfOutlined />} style={{ marginLeft: 10 }}>导出PDF</Button>
                </Header>
                <Content className="content">
                    <Table columns={columns} dataSource={filteredData} rowKey="id" />
                </Content>
            </Layout>
        </Layout>
    );
};

export default Violate;
